      "id": "modern-c04-l14-p01-009",
      "title": "平和に関する布告が無視された理由",
      "body": [
        "<strong class=\"source-bold\">ロシア革命の指導者</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>が、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和に関する<ruby>布告<rt>ふこく</rt></ruby></strong></span>」を発表して、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無併合<rt>むへいごう</rt></ruby>・無償金</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無賠償<rt>むばいしょう</rt></ruby></strong></span>】</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">・民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>」による和平を呼びかけたけど<strong class=\"source-bold\">連合国に無視された</strong>のは、各国が社会主義国の存在そのものを認めていなかったからだよ。"
      ],
