      "id": "modern-c04-l14-p01-028",
      "title": "フランスがアルザス・ロレーヌを獲得",
      "body": [
        "まず<strong class=\"source-bold\">フランス</strong>は、休戦条約を結んだ直後に占領した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス・ロレーヌ</strong></span>を獲得した。ここは<strong class=\"source-bold\">石炭や鉄鉱石</strong>が採れるし、<strong class=\"source-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争以来</strong>ずっと、フランスが「ゼッタイ取り返す！」って言ってたところだ。"
      ],
