      "body": [
        "第一次世界大戦が終わると、世界における<strong class=\"source-bold\">ヨーロッパの影響力が弱くなった</strong>よ。敗戦国ドイツは力を失い、戦争の被害がひどかったイギリスやフランスの影響力も低下、さらにロシア革命後に成立したソ連は国際関係から排除された。"
      ],
