      "title": "九カ国条約の参加国と中国の原則",
      "body": [
        "続いて、1922年2月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・日・仏</strong></span>・<strong class=\"source-bold\">伊・中国・オランダ・ベルギー・ポルトガル</strong>によって調印された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">九カ国条約</strong></span>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国</strong></span>の<strong class=\"source-bold\">主権・独立の尊重、門戸開放、機会均等、領土保全</strong>が決められた。"
      ],
