      "title": "海軍軍備制限条約と五国の比率",
      "body": [
        "ワシントン会議では<strong class=\"source-bold\">海軍の軍縮</strong>も話し合われ、1922年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワシントン海軍軍備制限条約</strong></span>が調印されたよ。この条約では、<strong class=\"source-bold\">アメリカ、イギリス、日本</strong>の3大海軍国に<strong class=\"source-bold\">フランス、イタリア</strong>を加えた5カ国の海軍<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">主力艦</strong></span>の<strong class=\"source-bold\">保有トン数</strong>の上限と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保有比率</strong></span>が決められ、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米：英：日</strong></span>：<strong class=\"source-bold\">仏：伊</strong> ＝ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">5：5：3</strong></span>：1.67：1.67」になった。"
      ],
      "plainBody": [
        "ワシントン会議では海軍の軍縮も話し合われ、1922年にワシントン海軍軍備制限条約が調印されたよ。この条約では、アメリカ、イギリス、日本の3大海軍国にフランス、イタリアを加えた5カ国の海軍主力艦の保有トン数の上限と保有比率が決められ、「米：英：日：仏：伊 ＝ 5：5：3：1.67：1.67」になった。"
      ],
