      "body": [
        "そこでドイツは「<strong class=\"source-bold\">賠償金が払えない金額だ！</strong>」っていうことを、<strong class=\"source-bold\">身をもって証明</strong>することにした。それが「<strong class=\"source-bold\"><ruby>履行<rt>りこう</rt></ruby>政策</strong>」だよ。これね、<strong class=\"source-bold\">賠償金を払ったら国家財政が破綻</strong>するってわかっているから、あえて<strong class=\"source-bold\">連合国の言うとおりに賠償金を支払って</strong>、払えなくなった時に「もう何をどうやっても、1円も払えませんけど……」って言ってやろう、っていう政策だ。"
      ],
