export const sourcePages = {
  "259": "<h2>259</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">第4章</strong></span></h1>\n<h1><span data-source-color=\"white\" data-source-background=\"pink\" style=\"color:#ffffff;background-color:#f0a0a0\"><strong class=\"source-bold\">戦間期と第二次世界大戦</strong></span></h1>",
  "260": "<h2>260</h2>\n<h3><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">ヴェルサイユ体制とワシントン体制</strong></span></h3>\n<p>それではいよいよ<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">第一次世界大戦後の世界</strong></u>に進むよ。第一次世界大戦はこれまでに経験したことのないような大きな戦争だったから、その影響で世界情勢も大きく変わっていくんだ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">ヴェルサイユ体制</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">261〜265ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↓</span></span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">国際連盟の成立</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">266〜267ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↓</span></span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">ワシントン体制</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">267〜270ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↓</span></span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">ドイツの賠償問題と協調外交</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">270〜274ページ</span></td></tr></tbody></table></div>\n<blockquote><p>ヨーロッパの戦後処理で一番大きな問題は、「ドイツをどうするか？」ってことだよ！</p></blockquote>\n<p>第一次世界大戦が終わって、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">戦場となったヨーロッパ</strong></u>はすっかり荒れ果てて、しかも、これまでのどんな戦争よりも大きな戦争を体験したことで、世界は大きく変わったんだ。各国は「二度と戦争を起こさないようにするにはどうしたらよいか？」ってことを考え始めた。しかし、そこには限界もあったんだ。「この戦争が起きたのは誰の責任なのか？」って考えた時、結局「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">敗戦国ドイツが悪い！</strong></u>」ってことになっちゃったから、対立はなくならなかったんだね。こうして形成されたのが<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヴェルサイユ体制</strong></u>だよ。さらに<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アジア</strong></u>では、勢力を拡大した<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">日本への警戒感</strong></u>が強まり、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ワシントン体制</strong></u>が形成された。そして、第一次世界大戦の戦後処理をおこなう過程で、すでに第二次世界大戦の原因も生まれてしまったんだよ。</p>\n<p>それじゃあ、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヴェルサイユ体制とワシントン体制</strong></u>の始まり〜。</p>",
  "261": "<h2>261</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ヴェルサイユ体制</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ヴェルサイユ体制</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><ruby>未曾有<rt>みぞう</rt></ruby>の世界大戦が終わって、世界情勢が大きく変わった！</strong></span></h4>\n<p>第一次世界大戦が終わって<strong class=\"source-bold\">世界情勢は大きく変化</strong>したよ。まず、ヨーロッパに残っていた<strong class=\"source-bold\">皇帝権の強い3つの帝国</strong>、<strong class=\"source-bold\">ハプスブルク家</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア＝ハンガリー帝国</strong></span>、<strong class=\"source-bold\">ロマノフ家</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア帝国</strong></span>、<strong class=\"source-bold\">ホーエンツォレルン家</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ帝国</strong></span>が崩壊してすべて<strong class=\"source-bold\">共和国</strong>になったから、19世紀のようにヨーロッパの君主たちの協調と勢力均衡でヨーロッパの国際秩序を維持するってことはできなくなった。</p>\n<p>なかでも、1917年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア革命</strong></span>によって<strong class=\"source-bold\">史上初の社会主義国が誕生</strong>したことは、各国にとってかなりの衝撃だった。だって、これまで政治的な発言力のなかった<strong class=\"source-bold\">労働者による政権</strong>ができたんだよ！ 「もし自分の国でも社会主義革命が起きたらどうしよう」って焦ったわけだ。<strong class=\"source-bold\">ロシア革命の指導者</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>が、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和に関する<ruby>布告<rt>ふこく</rt></ruby></strong></span>」を発表して、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無併合<rt>むへいごう</rt></ruby>・無償金</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無賠償<rt>むばいしょう</rt></ruby></strong></span>】</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">・民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>」による和平を呼びかけたけど<strong class=\"source-bold\">連合国に無視された</strong>のは、各国が社会主義国の存在そのものを認めていなかったからだよ。第一次世界大戦後の世界では「<strong class=\"source-bold\">資本主義 vs. 社会主義</strong>」っていう、国家の理念をめぐる対立も始まるんだ。</p>\n<p>そして、もう一つの大きな変化が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ合衆国</strong></span>の<strong class=\"source-bold\">台頭</strong>だよ。だって、アメリカの参戦が戦争の勝敗を決めたようなもんでしょ。しかも、<strong class=\"source-bold\">英仏はアメリカに膨大な借金をしている</strong>から（戦争での借金だから「<strong class=\"source-bold\"><ruby>戦債<rt>せんさい</rt></ruby></strong>」だよ）、アメリカの発言力は強くなるよね。だから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ<ruby>講和<rt>こうわ</rt></ruby>会議</strong></span>の原則は、<strong class=\"source-bold\">アメリカ大統領</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>が発表した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十四カ条</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十四カ条の平和原則</strong></span>】</strong>になった。これって、そもそもレーニンが発表した「<strong class=\"source-bold\">平和に関する布告</strong>」<strong class=\"source-bold\">を部分的にパクってる</strong>し（例えば「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族自決</strong></span>」ね）、秘密外交を暴露されて立場がなくなってる英仏を助けよう、って意味もある。そして、<strong class=\"source-bold\">ウィルソンの理想</strong>は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際平和機構の設立</strong></span>」だ。これは、<strong class=\"source-bold\">国際連盟として</strong>形になるよ。</p>\n<blockquote><p>「社会主義国ソ連の誕生」と「アメリカの台頭」。第一次世界大戦後の大きな変化だ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">米・英・仏の「3<ruby>巨頭<rt>きょとう</rt></ruby>」がパリ講和会議を主導したけれど……</strong></span></h4>\n<p>1919年1月、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ講和会議</strong></span>が開かれて、<strong class=\"source-bold\">米・英・仏・イタリア・日本</strong>の5大国を中心とする連合国27カ国の代表が、敗戦国、特にドイツに対する講和について話し合った。でもね、出席した国々の思惑はほんとバラバラだった。各国は<strong class=\"source-bold\">ロシア革命を波及させない</strong>ことなどでは一致したんだけど、<strong class=\"source-bold\">一番重要なドイツとの講和については、かなり意見が食い違っていた</strong>んだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "262": "<h2>262</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">第一次世界大戦中の和平提案</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和に関する<ruby>布告<rt>ふこく</rt></ruby></strong></span></span>［1917］</td><td>……ロシア革命の指導者：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>が発表</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無併合<rt>むへいごう</rt></ruby>・無償金</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無賠償<rt>むばいしょう</rt></ruby></strong></span>】</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">・民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>」に基づく和平を訴えた</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">連合国は黙殺</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span>レーニンは<strong class=\"source-bold\">ロシア帝国時代の秘密外交を暴露</strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十四カ条</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">の平和原則</strong></span>）</span>［1918］</td><td>……アメリカ大統領：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>が発表</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">“勝利なき平和”</strong>の理想を具体化した、大戦終結のための平和原則</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>レーニンの「<strong class=\"source-bold\">平和に関する布告</strong>」や<strong class=\"source-bold\">秘密外交の暴露</strong>に対抗</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>内容：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">軍備縮小・民族自決・国際平和機構の設立</strong></span>、<strong class=\"source-bold\">秘密外交の禁止</strong>、</td><td>海洋の自由、<ruby>関税障壁<rt>かんぜいしょうへき</rt></ruby>の<ruby>撤廃<rt>てっぱい</rt></ruby>、植民地問題の公正な解決　など</td></tr></tbody></table></div>\n<p>会議の主導権を握ったのは、<strong class=\"source-bold\">イギリス首相</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロイド＝ジョージ</strong></span>、<strong class=\"source-bold\">フランス首相</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クレマンソー</strong></span>、<strong class=\"source-bold\">アメリカ大統領</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>の3人だ。<strong class=\"source-bold\">フランス</strong>は、<ruby>普仏<rt>ふふつ</rt></ruby>戦争以来の<strong class=\"source-bold\">ドイツへの<ruby>復讐<rt>ふくしゅう</rt></ruby>心</strong>とフランスの安全確保のために、<strong class=\"source-bold\">ドイツを徹底的に弱らせたい</strong>！ でも、<strong class=\"source-bold\">イギリス</strong>はヨーロッパの<ruby>覇権<rt>はけん</rt></ruby>を維持したいから、<strong class=\"source-bold\">あんまりドイツは弱らせたくない</strong>。だって、ドイツが弱いと相対的にフランスが強くなる。そして、<strong class=\"source-bold\">アメリカ大統領ウィルソン</strong>は「<strong class=\"source-bold\">十四カ条</strong>」<strong class=\"source-bold\">のことしか言わない</strong>から、英仏は「話が長いよ」ってイライラ。で、米・英・仏がゴタゴタしてると、<strong class=\"source-bold\">イタリア</strong>が横から「<strong class=\"source-bold\"><ruby>未回収<rt>みかいしゅう</rt></ruby>のイタリア返して〜</strong>」って、話の腰を折るんだよ。英仏が「オマエは黙ってろ！」って言ったら、怒った<strong class=\"source-bold\">イタリアは途中で一時帰国</strong>しちゃった。そして日本は、ヨーロッパの問題には興味がない……。しかもウィルソンは、途中でインフルエンザで倒れちゃうし……。</p>\n<blockquote><p>結局、ヨーロッパの戦後処理の主導権は、英仏が握ったんだよ</p></blockquote>\n<p>結局、会議の決定には<strong class=\"source-bold\">英仏の意見が強く反映された</strong>。そして、会議の<strong class=\"source-bold\">最後の段階まで同盟国の代表は招かれず</strong>、ほとんど内容がまとまってからドイツが呼ばれ、<strong class=\"source-bold\">ヴェルサイユ宮殿<ruby>鏡<rt>かがみ</rt></ruby>の<ruby>間<rt>ま</rt></ruby></strong>で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ条約</strong></span>が調印されたんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ヴェルサイユ条約の内容は……「とにかくドイツを弱くしろ！」</strong></span></h4>\n<p><strong class=\"source-bold\">ヴェルサイユ条約では、とにかくドイツを弱らせた</strong>。ドイツへの復讐心の強かったフランスだけじゃなく、イギリスでも「ドイツを弱らせろ」って世論が強まって、選挙で保守党が人気を得ていたからね。自由党のロイド＝ジョージは焦ったんだろうな。だから、英仏はウィルソンの「<strong class=\"source-bold\">十四カ条</strong>」<strong class=\"source-bold\">をうまいこと利用して、ドイツを弱体化させる</strong>内容を決めたんだ。</p>",
  "263": "<h2>263</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ヴェルサイユ体制</u></p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">ヴェルサイユ条約［1919.6］</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ドイツ領の縮小と弱体化</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス・ロレーヌ</strong></span>を<strong class=\"source-bold\">フランス</strong>に<ruby>割譲<rt>かつじょう</rt></ruby></td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ポーランド<ruby>回廊<rt>かいろう</rt></ruby></strong>を<strong class=\"source-bold\">ポーランド</strong>に割譲</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ダンツィヒ</strong>は<strong class=\"source-bold\">国際連盟管理下の自由市</strong>となり、<strong class=\"source-bold\"><ruby>港湾<rt>こうわん</rt></ruby>使用権はポーランドへ</strong></td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ザール地方</strong>などは、<strong class=\"source-bold\">15年間国際連盟が管理</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">人民投票</strong>で<ruby>帰属<rt>きぞく</rt></ruby>を決定</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>メーメルは国際連盟管理となる</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">すべての海外植民地の<ruby>放棄<rt>ほうき</rt></ruby></strong></span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span>連合国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>委任統治<rt>いにんとうち</rt></ruby>領</strong></span>となった</td></tr><tr><td></td><td>南洋諸島：赤道以北は日本・以南は豪／トーゴ：英／カメルーン：仏<br>東アフリカ：英／南西アフリカ：南アフリカ連邦</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリアとの<ruby>合併<rt>がっぺい</rt></ruby>禁止</strong></span></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ドイツの軍備制限</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラインラント非武装</strong></span></td><td>……ドイツの<strong class=\"source-bold\">軍事施設の設置と駐兵の禁止</strong>。<br>ライン川<strong class=\"source-bold\">東岸50キロは非武装地帯</strong>とし、<strong class=\"source-bold\">西岸</strong>は連合国が15年間<strong class=\"source-bold\">保障<ruby>占領<rt>せんりょう</rt></ruby></strong></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>軍備制限</td><td>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">徴兵制</strong></span>の禁止。陸軍は10万人、海軍は1万5000人に制限。<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">空軍・潜水艦</strong></span>の<strong class=\"source-bold\">保有禁止</strong>。重砲・戦車の保有禁止</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span>巨額の賠償金</td><td>……<strong class=\"source-bold\">巨額の賠償金を課すことのみ</strong>決定。総額や支払い方式は<strong class=\"source-bold\">未決定</strong></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">ロンドン会議</strong>で<strong class=\"source-bold\">1320億金マルク</strong>に決定［1921］</td><td></td></tr></tbody></table></div>\n<p>まず<strong class=\"source-bold\">フランス</strong>は、休戦条約を結んだ直後に占領した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス・ロレーヌ</strong></span>を獲得した。ここは<strong class=\"source-bold\">石炭や鉄鉱石</strong>が採れるし、<strong class=\"source-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争以来</strong>ずっと、フランスが「ゼッタイ取り返す！」って言ってたところだ。さらにフランスは、「<strong class=\"source-bold\">ザールもよこせ！</strong>」って言ったんだけど、さすがに<strong class=\"source-bold\">米英に反対された</strong>。そこで<strong class=\"source-bold\">ザール地方は15年間連合国が占領</strong>したあと、<strong class=\"source-bold\">住民投票</strong>で帰属を決めることになった。そして、ポーランド分割で消滅していた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド</strong></span>が<strong class=\"source-bold\">独立</strong>して、バルト海沿岸の<strong class=\"source-bold\">ポーランド回廊はポーランド領</strong>になり、さらに港町の<strong class=\"source-bold\">ダンツィヒ</strong>の<strong class=\"source-bold\">港湾使用権がポーランドに</strong>与えられた。だから<strong class=\"source-bold\">東プロイセン（ドイツ領）</strong>が<strong class=\"source-bold\">飛び地</strong>になっちゃった。</p>\n<p>さらにドイツは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">すべての海外植民地を失った</strong></span>んだ（本当に100％だよ）。十四カ条にある「植民地問題の公正な解決」も「民族自決」もほぼ無視されて、<strong class=\"source-bold\">ドイツ領だった地域は国際連盟に引き渡され</strong>、適当な国に統治をまかせる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">委任統治</strong></span>になった。でもこれって、<strong class=\"source-bold\">戦勝国がドイツの植民地を奪っただけ</strong>だよな。だって、トーゴや東アフリカは<strong class=\"source-bold\">イギリス</strong>、カメルーンはフランス、太平洋の島々（南洋諸島）は<strong class=\"source-bold\">赤道以北が日本</strong>で、<strong class=\"source-bold\">赤道以南がオーストラリア</strong>、南西アフリカは<strong class=\"source-bold\">南アフリカ連邦</strong>が統治するこ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "264": "<h2>264</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<p>とになったんだもん。オーストラリアや南アフリカ連邦はイギリスの自治領だから、ほとんどが<strong class=\"source-bold\">イギリスの支配下になった</strong>ってことだよ。</p>\n<p>そして<strong class=\"source-bold\">ドイツ人の「民族<ruby>自決<rt>じけつ</rt></ruby>」も認められず</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツとオーストリアの<ruby>合併<rt>がっぺい</rt></ruby>は禁止</strong></span>されたんだ。</p>\n<blockquote><p>ドイツは戦前のヨーロッパの領土の約13％、人口の約10％を失ったよ</p></blockquote>\n<p>続いて、「<strong class=\"source-bold\">軍備縮小</strong>」にいくよ。ウィルソンはドイツの軍備縮小から始めて、各国を軍備縮小に向かわせようとしていたんだけど、<strong class=\"source-bold\">英仏は「ドイツの軍備だけ弱くすればいい」って考えた</strong>。特にフランスは、ドイツが二度と攻め込めないようにするため、「<strong class=\"source-bold\">独仏国境の軍備を制限しろ〜</strong>」って言い続け、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラインラントの非武装化</strong></span>と<strong class=\"source-bold\">連合国による保障<ruby>占領<rt>せんりょう</rt></ruby></strong>を認めさせた。そしてドイツでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">徴兵制が禁止</strong></span>され、第一次世界大戦で登場した<strong class=\"source-bold\">新兵器（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">空軍・潜水艦</strong></span>・戦車・重砲）の保有も禁止</strong>になったよ。あっ、<strong class=\"source-bold\">軍の保有そのものは禁止ではない</strong>から、正誤問題では気をつけてね！ 陸軍10万人、海軍1万5000人まではOKだ。</p>\n<p>さらに、ドイツに膨大な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>賠償金<rt>ばいしょうきん</rt></ruby></strong></span>を課すことになったんだけど、<strong class=\"source-bold\">ヴェルサイユ条約では金額は決まっていない</strong>。2年後に開かれた<strong class=\"source-bold\">ロンドン会議</strong>で<strong class=\"source-bold\">1320億金マルク</strong>という法外な金額に決まった。これは、当時の<strong class=\"source-bold\">ドイツのGNP（国民総生産）の約20年分</strong>！。でもこれ、払えるわけないよね！</p>\n<h4><strong class=\"source-bold\">〈ヴェルサイユ体制〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td><strong class=\"source-bold\">フィンランド</strong></td></tr><tr><td></td><td></td><td></td><td><strong class=\"source-bold\">エストニア</strong></td></tr><tr><td><strong class=\"source-bold\">イギリス</strong></td><td></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\">メーメル</span></span></td><td><strong class=\"source-bold\">ラトヴィア</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">オランダ</strong></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\">ダンツィヒ</span></span></td><td><strong class=\"source-bold\">リトアニア</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">ベルギー</strong></td><td><strong class=\"source-bold\">ドイツ共和国</strong></td><td><strong class=\"source-bold\">東プロイセン</strong><br>（ドイツ領の飛び地）</td></tr><tr><td></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"gray\" style=\"color:#777777\">ザール</span></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"gray\" style=\"color:#777777\">ラインラント</span></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\">ポーランド回廊</span></span></td></tr><tr><td></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\">アルザス・ロレーヌ</span></span></td><td><strong class=\"source-bold\">チェコスロヴァキア</strong></td><td><strong class=\"source-bold\">ポーランド</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">フランス</strong></td><td><strong class=\"source-bold\">オーストリア</strong></td><td><strong class=\"source-bold\">ハンガリー</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">イタリア</strong></td><td><strong class=\"source-bold\">ユーゴスラヴィア</strong><br>※</td><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td></td><td></td><td><strong class=\"source-bold\">ギリシア</strong></td><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td></td><td></td><td></td><td><strong class=\"source-bold\">トルコ</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"fill\" style=\"color:#f0a0a0\">■</span></td><td>新興の独立国</td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\">地名</span></span></td><td>ドイツが失った地域</td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">地名</span></td><td>ヴェルサイユ条約にかかわる地域</td></tr></tbody></table></div>\n<p>※建国当初は「セルブ＝クロアート＝スロヴェーン王国」</p>",
  "265": "<h2>265</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ヴェルサイユ体制</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">その他の敗戦国との<ruby>講和<rt>こうわ</rt></ruby>条約も結ばれ、東欧では新興独立国が出現！</strong></span></h4>\n<p>ドイツとのヴェルサイユ条約が結ばれたあと、<strong class=\"source-bold\">その他の敗戦国との講和条約も</strong>結ばれたよ。気をつけてほしいのは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア＝ハンガリー帝国</strong></span>は<strong class=\"source-bold\">敗戦で崩壊</strong>し、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア</strong></span>」と「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー</strong></span>」に分かれたから、<strong class=\"source-bold\">講和条約も別々</strong>だよ。</p>\n<p>まず、1919年9月には<strong class=\"source-bold\">オーストリア</strong>との<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サン＝ジェルマン条約</strong></span>で、正式に帝国が解体されて支配下の民族が独立し、領土が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア</strong></span>などの諸国に分割されたから、<strong class=\"source-bold\">オーストリアはドイツ人だけの国になった</strong>。その後、11月には<strong class=\"source-bold\">ブルガリア</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヌイイ条約</strong></span>、翌1920年6月には<strong class=\"source-bold\">ハンガリー</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリアノン条約</strong></span>が結ばれたけど、ひどい目にあったのはハンガリーだよ。<strong class=\"source-bold\">ハンガリー人（マジャール人）の3分の1が国外に住むこと</strong>になっちゃったから、不満が高まった。そして同年8月にはトルコとの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セーヴル条約</strong></span>も結ばれたよ。セーヴル条約は、西アジアのところで詳しく話すから、今は条約の名前だけ覚えておこう！</p>\n<h4><strong class=\"source-bold\">〈東欧の新興独立国〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>国名</td><td>支配していた国</td><td>備考</td></tr><tr><td><strong class=\"source-bold\">フィンランド</strong></td><td>ロシア</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エストニア</strong></span></td><td>ロシア</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラトヴィア</strong></span></td><td>ロシア</td><td>この3国を合わせて「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルト3国</strong></span>」</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リトアニア</strong></span></td><td>ロシア</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド</strong></span></td><td>露・独・墺</td><td>「十四カ条」で独立を支持</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア</strong></span></td><td>オーストリア</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー</strong></span></td><td>オーストリアと分離</td><td></td></tr><tr><td><strong class=\"source-bold\">セルブ＝クロアート＝スロヴェーン王国</strong></td><td>墺・ハンガリー・ブルガリア</td><td>のちに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア</strong></span>と改称［1929］</td></tr></tbody></table></div>\n<p>これらの条約により、<strong class=\"source-bold\">東ヨーロッパ</strong>では「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>」に基づいて、新しい独立国が生まれたんだけど、いろんな部分が不完全なんだよ。だって、「民族自決」っていうのは、本当なら「<strong class=\"source-bold\">1つの民族が1つの国</strong>」をつくるってことなんだけど、<strong class=\"source-bold\">東欧は1民族1国家になってない</strong>。なぜだろ？ それは、<strong class=\"source-bold\">英仏に都合のいいように独立国をつくった</strong>からだよ。つまり、「<strong class=\"source-bold\">ドイツと社会主義国ロシア（のちのソ連）を弱らせる</strong>」ために、「それなりにドイツ・ロシアに対抗できそうな国」をつくったからだ。例えば、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア</strong></span>は、「<strong class=\"source-bold\">チェコ</strong>」と「<strong class=\"source-bold\">スロヴァキア</strong>」が別の民族だし、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴスラヴィア</strong></span>なんか、「<strong class=\"source-bold\">南スラヴ人の小民族</strong>は全部くっつけちゃえ！」って感じで、ドイツを<ruby>牽制<rt>けんせい</rt></ruby>できるようなサイズの国をつくったんだもんね。もともとの国名<strong class=\"source-bold\">セルブ＝クロアート＝スロヴェーン王国</strong>は「<strong class=\"source-bold\">セルビア・クロアティア・スロヴェニア</strong>」だよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "266": "<h2>266</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">国際連盟の成立</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">国際連盟</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟</strong></span></span>［1920.1発足］</td><td>……史上初の集団的国際安全保障機構</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">アメリカ大統領</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十四カ条</strong></span>」に基づき設立</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">ヴェルサイユ条約</strong>で設立が決定</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>本部は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ</strong></span>（スイス）。発足時の加盟国は42カ国</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span>国際連盟の主要機関</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">総会</strong></span></td><td>……<strong class=\"source-bold\">最高議決機関</strong>。全加盟国による<strong class=\"source-bold\">1国1票</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全会一致制</strong></span></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">理事会</strong></span></td><td>……<strong class=\"source-bold\">常任理事国</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英・仏・伊・日</strong></span>。非常任理事国は、総会で選出</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>連盟事務局</td><td>……ジュネーヴに常置された</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">国際労働機関【ILO】</strong></td><td>……各国の労働問題の調整機関</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>国際知的協力委員会</td><td>……ユネスコの前身</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>国際連盟保健機関</td><td>……世界保健機関の前身</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">常設国際司法裁判所</strong></td><td>……オランダの<strong class=\"source-bold\">ハーグ</strong>に常設。強制権はない</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span>国際連盟の問題点</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">全会一致</strong>の議決方式</td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">重要事項の決定が遅延</strong>し、紛争解決が遅れた</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><ruby>制裁<rt>せいさい</rt></ruby>方式の不明瞭</td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">経済制裁</strong>や外交上の制裁にとどまる。<br><strong class=\"source-bold\">軍事制裁は不可</strong>。強制力は弱い</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">大国の不参加</strong></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米</strong></span>（孤立主義）の不参加、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独・墺</strong></span>（敗戦国）・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト＝ロシア</strong></span>（のちの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>・社会主義国）は排除</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「十四カ条」でうたわれた国際平和機構として、国際連盟が誕生！</strong></span></h4>\n<p>第一次世界大戦の被害は、これまでの戦争とは比べられないくらいひどいものだったから、<strong class=\"source-bold\">参戦した各国は「もう二度と戦争はしたくない！」</strong>って思っていた。だから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十四カ条</strong></span>をもとに、<strong class=\"source-bold\">ヴェルサイユ条約で史上初めての国際平和機構の設立</strong>が決まり、1920年1月、正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟</strong></span>が発足したよ。</p>\n<p><strong class=\"source-bold\">国際連盟の本部</strong>は<strong class=\"source-bold\">スイス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジュネーヴ</strong></span>に置かれ、設立当初は42か国が加盟した。最高議決機関は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">総会</strong></span>で、加盟国が<strong class=\"source-bold\">1国1票</strong>で投票したんだけど、決定は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全会一致</strong></span>が原則となったんだ。さらに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス・フランス・イタリア・日本</strong></span>の4国の<strong class=\"source-bold\">常任理事国</strong>と、総会で選出された<strong class=\"source-bold\">非常任理事国</strong>（当初4カ国、1922年から6カ国、1926年から9カ国になったよ）で構成される<strong class=\"source-bold\">理事会</strong>が重要な議決機関になった。</p>\n<p>じゃあ、なんで常任理事国がこの4国になったんだろう？</p>",
  "267": "<h2>267</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ワシントン体制</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">大国の不参加で連盟の影響力が弱い！ 本当に戦争を防げるの？</strong></span></h4>\n<p>国際連盟の一番の問題点は、<strong class=\"source-bold\">大国の不参加</strong>だよ。第一次世界大戦のおもな参戦国は、<strong class=\"source-bold\">連合国（三国協商側）</strong>が<strong class=\"source-bold\">イギリス、フランス、ロシア</strong>と、あとから参戦した<strong class=\"source-bold\">イタリア、日本、アメリカ</strong>だったね。そして<strong class=\"source-bold\">同盟国（三国同盟側）</strong>が<strong class=\"source-bold\">ドイツとオーストリア</strong>だ。でも、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ・オーストリア</strong></span>は敗戦国として排除されたから参加できない。それに、<strong class=\"source-bold\">ロシア革命で社会主義国</strong>となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト＝ロシア</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>）は、<strong class=\"source-bold\">各国が承認していない</strong>から加盟できないんだ。さらに、国際連盟を提唱した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>は、民主党の<strong class=\"source-bold\">ウィルソンが理想主義に突っ走り</strong>「共和党の同意を取らなきゃいけない」って意識が弱くて、いざヴェルサイユ条約を<ruby>批准<rt>ひじゅん</rt></ruby>する時に、<strong class=\"source-bold\">共和党が伝統的な孤立主義に傾き、上院で否決</strong>してしまった。アメリカは、外交については上院の決定が優先されるからね。こうして、<strong class=\"source-bold\">アメリカも不参加</strong>になったんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><span data-source-border=\"dashed-black\" style=\"border:1px dashed #001000;padding:0 0.2em\">連合国</span></td><td></td><td></td><td></td><td><span data-source-marker=\"dashed-line\">┆</span></td><td><span data-source-border=\"dashed-black\" style=\"border:1px dashed #001000;padding:0 0.2em\">同盟国</span></td><td></td></tr><tr><td><span data-source-border=\"circle\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英</strong></span></span></td><td><span data-source-border=\"circle\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">仏</strong></span></span></td><td><span data-source-border=\"circle\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em;text-decoration:line-through;text-decoration-color:#001000\"><strong class=\"source-bold\">露</strong></span></td><td><span data-source-border=\"circle\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">伊</strong></span></span></td><td><span data-source-border=\"circle\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日</strong></span></span></td><td><span data-source-border=\"circle\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em;text-decoration:line-through;text-decoration-color:#001000\"><strong class=\"source-bold\">米</strong></span></td><td><span data-source-marker=\"dashed-line\">┆</span></td><td><span data-source-border=\"circle\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em;text-decoration:line-through;text-decoration-color:#001000\"><strong class=\"source-bold\">独</strong></span></td><td><span data-source-border=\"circle\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"border:1px solid #001000;border-radius:50%;padding:0.2em;text-decoration:line-through;text-decoration-color:#001000\"><strong class=\"source-bold\">墺</strong></span></td></tr><tr><td></td><td></td><td><span data-source-marker=\"arrow\">↓</span></td><td></td><td></td><td><span data-source-marker=\"arrow\">↓</span></td><td></td><td><span data-source-marker=\"arrow\">↓</span></td><td></td></tr><tr><td></td><td></td><td>社会主義国（のちのソ連）は排除</td><td></td><td></td><td>上院の反対で<br>不参加</td><td></td><td>敗戦国は排除</td><td></td></tr></tbody></table></div>\n<p>結局、残った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本</strong></span>が国際連盟の理事会で<strong class=\"source-bold\">常任理事国</strong>になったんだ。でも、第一次世界大戦を経て<strong class=\"source-bold\">世界一の大国になったアメリカが参加しない</strong>のは、<strong class=\"source-bold\">連盟そのものの影響力が弱くなる</strong>から、ちょっと問題だよね。</p>\n<p>問題点はそれだけじゃないよ。戦争をしそうになった国に対する制裁では、<strong class=\"source-bold\">軍事制裁ができずに経済制裁</strong>や外交上の制裁にとどまるから、ちょっと<strong class=\"source-bold\">強制力が弱い</strong>よね。まぁ、軍隊送ったからうまくいくってもんでもないけどさ。しかも、制裁を決める時も、<strong class=\"source-bold\">総会の議決は全会一致制</strong>だから、重要なことになればなるほど各国の意見が対立して、<strong class=\"source-bold\">決定が遅れてしまう</strong>。結果的に国際連盟は第二次世界大戦を阻止できなかったよね。とはいっても、国際平和機構がつくられた意義は大きいよ。だって1920年代には、いくつか戦争が起きるのを防げたし、中国やシャム（タイ）などの新興国が、主体的に国際政治にかかわる機会ができたからね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ワシントン体制</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アメリカ主導のワシントン会議で、アジア太平洋の国際秩序を形成！</strong></span></h4>\n<p>第一次世界大戦が終わると、世界における<strong class=\"source-bold\">ヨーロッパの影響力が弱くなった</strong>よ。敗戦国ドイツは力を失い、戦争の被害がひどかったイギリスやフランスの影響力も低下、さらにロシア革命後に成立したソ連は国際関係から排除された。こうして、ヨーロッパが力を弱めるなかで、<strong class=\"source-bold\">勢力を拡大したのがアメリカと日本</strong>だよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "268": "<h2>268</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<p>日本は、大戦中に<strong class=\"source-bold\">中国や太平洋に進出してドイツの権益を奪う</strong>と、さらに<ruby>軍閥<rt>ぐんばつ</rt></ruby>政権を支援して中国で勢力を拡大した。実際、この時期に<strong class=\"source-bold\">アジアに進出する力を持っていたのは、アメリカと日本だけ</strong>だったからね。しかも、大戦で協力した<strong class=\"source-bold\">アメリカとイギリスの関係が強まる</strong>と日英同盟の意義も薄れて、むしろ<strong class=\"source-bold\">日本のアジア進出への警戒感</strong>が強くなってきたんだ。</p>\n<p>さらに大戦後には、<strong class=\"source-bold\">世界各国が「海軍の拡大競争をストップしたい！」って思っていた</strong>んだよ。財政難になったイギリスは、軍艦建造どころじゃない。アメリカも大戦中にはむちゃくちゃ海軍を強化したんだけど、戦後は国内で「もう軍備拡大は終わりでいいだろ」って世論が高まっていたんだ。日本だって、このままアメリカに対抗して軍艦を造り続けるのは、当時の国力では無理だよ。</p>\n<p>こうした国際情勢のなかで、アジア・太平洋地域の国際秩序の形成や海軍の軍縮で主導権を握ったのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>だよ。ただ、そのウラには「日本<ruby>封<rt>ふう</rt></ruby>じ」が隠れている。アメリカは、第一次世界大戦中に日英同盟を口実に中国進出を進めた日本を封じ込めて、アジア・太平洋でアメリカ優位の体制をつくりたかったんだね。</p>\n<p><strong class=\"source-bold\">アメリカ大統領ハーディング</strong>の提唱で開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワシントン会議</strong></span>では、<strong class=\"source-bold\">アジア・太平洋地域の「現状維持」</strong>を口実に3つの条約が結ばれたんだけど、中身をよく考えてみると「日本の勢力拡大を抑える」って意図が見えるよ。</p>\n<h4><strong class=\"source-bold\">〈ワシントン会議で締結された条約〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四カ国条約</strong></span>［1921］</td><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス</strong></span>で調印<br><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">太平洋地域</strong></span>の領土・権益の相互尊重と<strong class=\"source-bold\">現状維持</strong><br><span data-source-color=\"gray\" style=\"color:#777777\">●</span>太平洋の各諸島の非軍事基地化</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">九カ国条約</strong></span>［1922］</td><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・日・仏</strong></span>・<strong class=\"source-bold\">伊・中国・蘭・ベルギー・ポルトガル</strong><br><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国</strong></span>の<strong class=\"source-bold\">主権・独立</strong>の尊重、<strong class=\"source-bold\">領土<ruby>保全<rt>ほぜん</rt></ruby></strong>、機会均等、<strong class=\"source-bold\"><ruby>門戸開放<rt>もんこかいほう</rt></ruby></strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワシントン海軍軍備制限条約</strong></span>［1922］</td><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・日・仏・伊</strong></span>の5カ国で<ruby>締結<rt>ていけつ</rt></ruby><br><span data-source-color=\"gray\" style=\"color:#777777\">●</span>海軍<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">主力艦</strong></span>の<strong class=\"source-bold\">保有トン数</strong>の上限と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保有比率</strong></span>を決定<br><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米：英：日</strong></span>：<strong class=\"source-bold\">仏：伊</strong> ＝ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">5：5：3</strong></span>：1.67：1.67</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">太平洋をめぐる四カ国条約。結果は……日英同盟が<ruby>破棄<rt>はき</rt></ruby>された！</strong></span></h4>\n<p>1921年12月に調印された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四カ国条約</strong></span>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">太平洋地域</strong></span>における領土・<strong class=\"source-bold\">権益の相互尊重と現状維持</strong>、<strong class=\"source-bold\">各諸島の非軍事基地化</strong>を決めたよ。「現状維持」っていうと普通に聞こえるかもしれないけど、<strong class=\"source-bold\">この時点で太平洋地域に進出できるのは</strong>、第一次世界大戦で力をつけた<strong class=\"source-bold\">アメリカと日本だけ</strong>。会議を主導するアメリカが「日本はダメだけど、アメリカは行くぜ！」って言うのもおかしいでしょ。だから現状維持というのは「<strong class=\"source-bold\">日本にこれ以上勢力拡大させない</strong>」っていう「日本封じ」になるんだ。</p>\n<p>そして会議の場で、日本は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・日・仏</strong></span>の4カ国がみんなで助け合うんだから、<strong class=\"source-bold\">特定の2カ国で助け合わなくていいですね</strong>」って言われた。特定の2カ国っ</p>",
  "269": "<h2>269</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ワシントン体制</u></p>\n<p>ていうのは<strong class=\"source-bold\">日英同盟</strong>のことだよ。つまり、<strong class=\"source-bold\">四カ国条約</strong>ができたことで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日英同盟が解消</strong></span>されて、<strong class=\"source-bold\">米英が連携して日本を包囲する体制</strong>ができたんだ！。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">中国に関する九カ国条約では、アメリカの主張が認められた！</strong></span></h4>\n<p>続いて、1922年2月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米・英・日・仏</strong></span>・<strong class=\"source-bold\">伊・中国・オランダ・ベルギー・ポルトガル</strong>によって調印された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">九カ国条約</strong></span>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国</strong></span>の<strong class=\"source-bold\">主権・独立の尊重、門戸開放、機会均等、領土保全</strong>が決められた。でも、読んでて気づいたかな？「門戸開放」「機会均等」「領土保全」って、<strong class=\"source-bold\">アメリカの門戸開放宣言</strong>だよね。つまりこの条約では、<strong class=\"source-bold\">アメリカの主張がほぼ承認された</strong>んだ。これが9カ国で認められたってことは、アメリカの「門戸開放宣言」と日本の「二十一カ条」を相互承認した<strong class=\"source-bold\">石井・ランシング協定が失効</strong>したってことだ！。こうして、日本の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">二十一カ条要求</strong></span>は<strong class=\"source-bold\">事実上効力がなくなり</strong>、日本は米英が<ruby>仲介<rt>ちゅうかい</rt></ruby>した日中交渉によって、<strong class=\"source-bold\"><ruby>山東<rt>さんとう</rt></ruby>半島の旧ドイツ権益などを中国に返還</strong>することになったんだよ。</p>\n<blockquote><p>四カ国条約と九カ国条約は、日本の勢力拡大を抑えようって意図が見え見えだよ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">海軍軍備制限条約が結ばれたけど……米英の優位が保障された！</strong></span></h4>\n<p>ワシントン会議では<strong class=\"source-bold\">海軍の軍縮</strong>も話し合われ、1922年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワシントン海軍軍備制限条約</strong></span>が調印されたよ。この条約では、<strong class=\"source-bold\">アメリカ、イギリス、日本</strong>の3大海軍国に<strong class=\"source-bold\">フランス、イタリア</strong>を加えた5カ国の海軍<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">主力艦</strong></span>の<strong class=\"source-bold\">保有トン数</strong>の上限と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保有比率</strong></span>が決められ、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米：英：日</strong></span>：<strong class=\"source-bold\">仏：伊</strong> ＝ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">5：5：3</strong></span>：1.67：1.67」になった。また、保有トン数も米英が52万5000トンまでになり、<strong class=\"source-bold\">今後10年間は新しい主力艦は造らない</strong>ことにした。<strong class=\"source-bold\">米・英の比率が同じ</strong>なのは、戦後の国力の変化の表れだよ。</p>\n<p>この軍縮交渉では、まずアメリカが「建造中の主力艦すべてを<ruby>廃棄<rt>はいき</rt></ruby>しよう」と提案した。建造中の主力艦の数はアメリカが一番多かったから、かなり大胆な提案だね。日本は「対米70％にしてほしい」と主張したんだけど、アメリカが西太平洋の海軍基地を強化しないという条件で、「米：英：日」の比率を「5：5：3」で合意し、比率にあうように<strong class=\"source-bold\">旧式の主力艦が廃棄</strong>された。この条約の内容はこののち10年以上守られたから軍縮条約としては一定の成果はあったけど、各国は補助艦の増強で埋め合わせたんだ。だから、このあと<strong class=\"source-bold\">補助艦に関する軍縮会議</strong>が開かれるよ。</p>\n<p>1927年には、<strong class=\"source-bold\">ジュネーヴ軍縮会議</strong>が開かれて<strong class=\"source-bold\">米・英・日の補助艦の軍縮</strong>について話し合われたんだけど、<strong class=\"source-bold\">フランスやイタリアが不参加</strong>で、<strong class=\"source-bold\">合意もできなかった</strong>。そして、1930年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロンドン軍縮会議</strong></span>が開かれて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">補助艦</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保有比率</strong></span>を「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米：英：日</strong></span> ＝ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">10：10：7弱</strong></span>（6.975）」とすることに決まった。<strong class=\"source-bold\">ロンドン軍縮会議はすでに世界<ruby>恐慌<rt>きょうこう</rt></ruby>後</strong>だよ。日本では海軍がこの決定を不満として政府への反発を強め（「<strong class=\"source-bold\"><ruby>統帥<rt>とうすい</rt></ruby><ruby>権干犯<rt>けんかんぱん</rt></ruby>問題</strong>」）、軍部が台頭するきっかけになったんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "270": "<h2>270</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ヴェルサイユ体制とワシントン体制。抑え込まれたのはドイツと日本だ！</strong></span></h4>\n<p>さて、ここまで<strong class=\"source-bold\">ヴェルサイユ体制とワシントン体制</strong>の形成を見てきたんだけど、この体制のなかに、すでに<strong class=\"source-bold\">第二次世界大戦の対立が現れている</strong>のに気づいたかな？</p>\n<p><strong class=\"source-bold\">ヨーロッパ</strong>で形成された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ体制</strong></span>では、<strong class=\"source-bold\">敗戦国ドイツを徹底的に抑え込む</strong>って方針がとられたよね。だって、ヴェルサイユ条約の内容はドイツを弱らせるものばかりだったでしょ。当然、ドイツ国内で「こんな体制<ruby>潰<rt>つぶ</rt></ruby>してやる！」って声が出てきてもおかしくないよね。<strong class=\"source-bold\">ヴェルサイユ体制の中心はイギリスとフランス</strong>だ！ 一方、<strong class=\"source-bold\">アジア</strong>で形成された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワシントン体制</strong></span>では、第一次世界大戦で力をつけた<strong class=\"source-bold\">日本の勢力拡大を警戒</strong>して、四カ国条約や九カ国条約などが結ばれたよね。<strong class=\"source-bold\">ワシントン体制を主導したのはアメリカとイギリス</strong>だ。</p>\n<p>もちろん、いきなり世界大戦が始まるわけじゃないし、各国とも戦後の<ruby>復興<rt>ふっこう</rt></ruby>が進むまでは世界が安定していたほうがいいと思ってる。でも、約10年後の<strong class=\"source-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong>で各国の経済が<ruby>破綻<rt>はたん</rt></ruby>すると、この時期に形成された包囲網が<strong class=\"source-bold\">ドイツと日本を苦しめ</strong>、結果として<strong class=\"source-bold\">包囲している米・英・仏</strong>と<strong class=\"source-bold\">包囲されている独・日</strong>の対立が激しくなり、世界は<strong class=\"source-bold\">第二次世界大戦に向かっていく</strong>んだ。つまり、<strong class=\"source-bold\">第二次世界大戦の対立（米英仏 vs. 独日）は、第一次世界大戦の戦後処理のなかで形成された</strong>ものなんだよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ドイツの賠償問題と協調外交</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">ドイツの賠償問題と協調外交</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルール<ruby>占領<rt>せんりょう</rt></ruby></strong></span></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルール出兵</strong></span>】</strong>［1923〜25］</td><td>……<strong class=\"source-bold\">フランス・ベルギー軍</strong>による</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span>ドイツ国内に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">破局的なインフレーション</strong></span>を招き、経済は完全に破綻</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レンテンマルク</strong></span>発行［1923］</td><td>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュトレーゼマン</strong></span>首相による新紙幣の発行</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドーズ案</strong></span></span>［1924］</td><td>……<strong class=\"source-bold\">ドイツの<ruby>賠償<rt>ばいしょう</rt></ruby>問題</strong>にアメリカが<ruby>介入<rt>かいにゅう</rt></ruby></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">フランスはルール地方より撤兵</strong></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span>協調外交の進展</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロカルノ条約</strong></span>［1925］</td><td>……<strong class=\"source-bold\">スイス</strong>のロカルノで<ruby>締結<rt>ていけつ</rt></ruby></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>独外相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュトレーゼマン</strong></span>、仏外相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブリアン</strong></span>が中心</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ラインラントの現状維持、非武装化</strong>の確認（ライン保障条約）</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツの国際連盟加盟</strong></span>が決定（<strong class=\"source-bold\">常任理事国</strong>として）。<strong class=\"source-bold\">正式加盟は翌年</strong>［1926］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">不戦条約</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケロッグ・ブリアン条約</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">協定</strong></span>）】</strong>［1928］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">アメリカ国務長官</strong>：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケロッグ</strong></span>、<strong class=\"source-bold\">フランス外相</strong>：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブリアン</strong></span>が主導</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>パリで15カ国が調印。のちに63カ国が参加</td><td></td></tr></tbody></table></div>",
  "271": "<h2>271</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ドイツの賠償問題と協調外交</strong></u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツの賠償金が支払い不能になると……フランスがルール地方を占領！</strong></span></h4>\n<p>第一次世界大戦に勝ったとはいえ、<strong class=\"source-bold\">イギリスやフランスなどの戦勝国</strong>も戦争で大きな被害を受けて、<strong class=\"source-bold\">国内の産業が衰退</strong>してしまった。さらに、戦争中にアメリカにとんでもない額の借金（<strong class=\"source-bold\"><ruby>戦債<rt>せんさい</rt></ruby></strong>）をしちゃったから、両国は「<strong class=\"source-bold\">ドイツからの賠償金で戦債を返そう！</strong>」って考えたんだ。<strong class=\"source-bold\">ヴェルサイユ条約では賠償金をいくらにするか決まっていなかった</strong>んだけど、1921年の<strong class=\"source-bold\">ロンドン会議</strong>で正式に<strong class=\"source-bold\">1320億金マルク</strong>に決定された。これは、当時のドイツの国民総生産（GNP）の約20年分だから、はっきり言って払えるような金額じゃないよ。</p>\n<p>ドイツ政府は「こんな金額は支払い不可能だ！」って抗議したけど、最終的には受け入れるしかなかった。そこでドイツは「<strong class=\"source-bold\">賠償金が払えない金額だ！</strong>」っていうことを、<strong class=\"source-bold\">身をもって証明</strong>することにした。それが「<strong class=\"source-bold\"><ruby>履行<rt>りこう</rt></ruby>政策</strong>」だよ。これね、<strong class=\"source-bold\">賠償金を払ったら国家財政が破綻</strong>するってわかっているから、あえて<strong class=\"source-bold\">連合国の言うとおりに賠償金を支払って</strong>、払えなくなった時に「もう何をどうやっても、1円も払えませんけど……」って言ってやろう、っていう政策だ。そして<strong class=\"source-bold\">1921年末には、本当に財政が破綻して、賠償支払いが不能になった</strong>。</p>\n<p>この時期にドイツは、同じように<strong class=\"source-bold\">ヴェルサイユ体制から除外されているソ連</strong>と交渉し、資本主義国のなかでは最初に<strong class=\"source-bold\">ソ連を承認</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラパロ条約</strong></span>を結び、なんとか経済再建の道を探ったんだ。でもこれを見たフランスは、「社会主義国と付き合うとは、ドイツは信用できない」と反発した。しかも<strong class=\"source-bold\">フランス</strong>は、ドイツからの賠償金がないとアメリカへの戦債が払えないから、ついに<strong class=\"source-bold\">直接行動に出た</strong>んだよ。</p>\n<p>1923年、<strong class=\"source-bold\">ドイツの賠償支払いが遅れていること</strong>を口実に、「直接ドイツに乗り込んで、賠償を取り立ててやる〜」と、<strong class=\"source-bold\">フランスとベルギー</strong>が一緒になって、<strong class=\"source-bold\">ドイツ最大の鉱山・工業地帯</strong>である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルール地方</strong></span>に軍を送り込んできた。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルール占領</strong></span>だよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツ人はサボって抵抗。気づけばとんでもないインフレになった！</strong></span></h4>\n<p>ルール占領を受けた<strong class=\"source-bold\">ドイツ</strong>は、フランスが得をしないように、とにかく<strong class=\"source-bold\">一切の協力をしないことにした</strong>。とにかくサボりまくる（ちゃんとした言い方だと「<strong class=\"source-bold\">サボタージュ</strong>」）。これ、教科書では<strong class=\"source-bold\">消極的抵抗</strong>とか不服従運動って書いてあるよ。そしたらフランスはさらに軍隊を増やしてきた！ だから、ドイツはまたサボる……もう悪循環どころじゃない。</p>\n<p>消極的抵抗をやったために<strong class=\"source-bold\">鉱山や工業の生産が激減</strong>し、ますます<strong class=\"source-bold\">ドイツの産業は混乱</strong>した。しかも、国内の労働者には給料を払わなきゃいけないけど、そんなお金はない。この時ドイツ政府は、「もう、お<ruby>札<rt>さつ</rt></ruby>を刷ってごまかしとけ〜」とばかりに、<strong class=\"source-bold\">紙幣を増刷しまくった</strong>。そしたら、<strong class=\"source-bold\">ドイツの通</strong></p>\n<blockquote><p>ルール占領のせいでドイツ経済はガタガタだよ。なんと物価が1兆倍だもん！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "272": "<h2>272</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<p><strong class=\"source-bold\">貨（マルク）が暴落</strong>して、物価がとんでもないことになったんだ。だって、ルール<ruby>占領<rt>せんりょう</rt></ruby>前に1マルクだったパンの値段は、ついに1兆マルク！。<strong class=\"source-bold\">物価が1兆倍</strong>だよ……。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">破局的なインフレーション</strong></span>で、ドイツ経済は完全に<ruby>破綻<rt>はたん</rt></ruby>したんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">新紙幣でインフレを収束。そして、アメリカが<ruby>賠償<rt>ばいしょう</rt></ruby>問題に<ruby>介入<rt>かいにゅう</rt></ruby>！</strong></span></h4>\n<p>こうなると、ドイツだけじゃなく<strong class=\"source-bold\">全ヨーロッパの経済再建が難しくなる</strong>。しかも、ドイツでは<strong class=\"source-bold\">労働者が生活できなくなった</strong>から、国内では政府を倒そうって声も出始めた。首相となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュトレーゼマン</strong></span>は、混乱を抑えるために動き出したんだ。</p>\n<p><strong class=\"source-bold\">シュトレーゼマン</strong>はまず、<strong class=\"source-bold\">消極的抵抗を停止</strong>して、共産党が起こそうとしていた反乱を抑えた。そして、1923年11月には、不動産収入を<ruby>担保<rt>たんぽ</rt></ruby>とする新紙幣<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レンテンマルク</strong></span>（「1レンテンマルク＝1兆マルク」だよ）を発行して紙幣の量を減らし、<strong class=\"source-bold\">奇跡的にインフレーションを収めた</strong>。さらにシュトレーゼマンは「<strong class=\"source-bold\">ドイツ経済を再建するためには、英仏などの戦勝国とも協力しなきゃいかん</strong>」と思い、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">協調外交</strong></span>」に転換したんだ。</p>\n<p>そして<strong class=\"source-bold\">イギリス</strong>も、ドイツ経済が<ruby>復興<rt>ふっこう</rt></ruby>しないとヨーロッパ全体が復興しないことに気づいていたから、経済大国になった<strong class=\"source-bold\">アメリカにドイツの賠償問題にかかわるように働きかけた</strong>。そして<strong class=\"source-bold\">アメリカ</strong>も、<strong class=\"source-bold\"><ruby>戦債<rt>せんさい</rt></ruby>を回収するために</strong>ドイツの復興を助けたほうがいいと思ったから、「じゃあ、<strong class=\"source-bold\">アメリカ（の金融業界）がドイツを助けましょう</strong>」ってことになった。でもね、アメリカ国内では孤立主義（ヨーロッパの政治にはかかわらない）が強かったから、「あくまでも<strong class=\"source-bold\">民間の財政家ドーズ</strong>を中心とする委員会（ドーズ委員会）の案ですよ」っていうタテマエで、報告書がまとめられたんだ。</p>\n<h4><strong class=\"source-bold\">〈ドーズ案によるお金の流れ〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"circle\" style=\"border:2px solid #001000;border-radius:50%;padding:0.2em\"><strong class=\"source-bold\">アメリカ</strong><br>アメリカに<br>富が集中</span></td><td><strong class=\"source-bold\">アメリカ資本をドイツに貸与</strong><br><span data-source-marker=\"arrow\" style=\"color:#001000\">→</span></td><td><span data-source-border=\"circle\" style=\"border:2px solid #e52715;border-radius:50%;padding:0.2em\"><strong class=\"source-bold\">ドイツ</strong><br>経済復興が進む</span></td></tr><tr><td><strong class=\"source-bold\">英仏が戦債支払い</strong><br><span data-source-marker=\"arrow\" style=\"color:#f0a0a0\">↖</span></td><td><span data-source-border=\"circle\" style=\"border:2px solid #f0a0a0;border-radius:50%;padding:0.2em\"><strong class=\"source-bold\">イギリス</strong><br>経済復興が進む</span><br><span data-source-border=\"circle\" style=\"border:2px solid #f0a0a0;border-radius:50%;padding:0.2em\"><strong class=\"source-bold\">フランス</strong><br>経済復興が進む</span></td><td><span data-source-marker=\"arrow\" style=\"color:#e52715\">↙</span><br><strong class=\"source-bold\">ドイツが賠償金<br>支払い</strong></td></tr></tbody></table></div>\n<blockquote><p>これって、アメリカのお金がヨーロッパをぐるぐる回ってるだけだよね</p></blockquote>",
  "273": "<h2>273</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ドイツの賠償問題と協調外交</strong></u></p>\n<p>こうして1924年にできたのが、ドイツの新しい賠償方式<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドーズ案</strong></span>だよ。ここでは、<strong class=\"source-bold\">アメリカ資本によるヨーロッパ復興</strong>のシナリオが提案されたよ。まず、<strong class=\"source-bold\">アメリカ資本（民間資本）をドイツに投資</strong>することでドイツ経済を復興させて、<strong class=\"source-bold\">ドイツが</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">賠償金</strong></span>を払えるようにする。そして、<strong class=\"source-bold\">ドイツが払った賠償金</strong>を使って英仏の経済を復興させて、<strong class=\"source-bold\">英仏</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦債</strong></span><strong class=\"source-bold\">支払い</strong>ができるようにする。こうすれば、<strong class=\"source-bold\">ドイツの賠償金支払いと経済復興</strong>が両立できるよね。</p>\n<p>ただね、<strong class=\"source-bold\">ドーズ案には不十分なところもある</strong>んだよ。フランスが「戦債を減らしてくれないなら、ドイツの賠償金を減らすのは納得できん」って言うから、<strong class=\"source-bold\">賠償金総額は減額しなかった</strong>。これ、正誤問題でよく聞かれるよ！ ただ、<strong class=\"source-bold\">当面の支払い（1年あたりの支払額）は軽減</strong>したので、ドイツは経済復興に向かうことができる。<strong class=\"source-bold\">賠償金の減額</strong>は、1929年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヤング案</strong></span>（358億金マルクになった！）までやらないからね。</p>\n<p>もう一つ、ドーズ案によって<strong class=\"source-bold\">ヨーロッパの復興が進んだ</strong>けど、結局は<strong class=\"source-bold\">ヨーロッパ経済がアメリカ1国（しかも民間）に完全に頼る</strong>ってことだから、アメリカが不景気になったら……ヨーロッパの経済が一緒に倒れる。ただこの時点では、アメリカの支援がないとヨーロッパの再建はできなかったからね。こうして各国がドーズ案を受け入れて、<strong class=\"source-bold\">フランス</strong>もこれに基づいて<strong class=\"source-bold\">ルールから<ruby>撤退<rt>てったい</rt></ruby></strong>したので、ドイツの賠償金をめぐる混乱は収まったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロカルノ条約でドイツが国際社会に復帰し、国際協調が進んだ！</strong></span></h4>\n<p><strong class=\"source-bold\">賠償問題が一段落する</strong>と、ヨーロッパ各国は「<strong class=\"source-bold\">なんでこんな状況になったのか？</strong>」ってことを冷静になって考えた。って、結論はわかってるじゃん。<strong class=\"source-bold\">第一次世界大戦によってヨーロッパ全体の地位が落ちて</strong>、田舎の国だと思っていたアメリカが、気づけば世界一になっていた。「こりゃ、二度とあんな戦争を起こしちゃマズい！」。じゃあ、どうすればいいか？ <strong class=\"source-bold\">ヨーロッパの安全保障</strong>を考えると、このまま<strong class=\"source-bold\">ドイツを排除し続けるわけにはいかない</strong>よね。</p>\n<p>ただ、<strong class=\"source-bold\">フランスはドイツを信用していない</strong>。だから、ドイツが二度と攻めてこないという確約がほしかった。そしてドイツの<strong class=\"source-bold\">外相</strong>となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュトレーゼマン</strong></span>も、アメリカや英仏との関係を改善しない限りドイツの復興は不可能だと思っていたから、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">協調外交</strong></span>」に転換した。こうして、<strong class=\"source-bold\">ドイツ外相シュトレーゼマン、フランス外相</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブリアン</strong></span>、<strong class=\"source-bold\">イギリス外相オースティン＝チェンバレン</strong>を中心に合意がつくられ、1925年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロカルノ条約</strong></span>が結ばれたんだ。</p>\n<p><strong class=\"source-bold\">ロカルノ条約</strong>では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラインラント</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏国境</strong></span>）<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">の現状維持</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非武装化</strong></span>が再確認され（ライン保障条約）、さらに<strong class=\"source-bold\">紛争の際には<ruby>仲裁<rt>ちゅうさい</rt></ruby>裁判をおこなうこ</strong></p>\n<blockquote><p><strong class=\"source-bold\">ドイツの国際連盟加盟</strong>は、ロカルノ条約調印の「<strong class=\"source-bold\">翌年</strong>」だから、正誤問題では気をつけて！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "274": "<h2>274</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第14回</strong></span> ヴェルサイユ体制とワシントン体制</p>\n<p>とが決められた。そして、この条約では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツの国際連盟加盟</strong></span>が決まり、翌年、<strong class=\"source-bold\">常任理事国</strong>として正式に加盟したよ。</p>\n<p>こうした<strong class=\"source-bold\">国際協調の動き</strong>は、世界全体に「平和を維持しよう」という空気をつくり出したんだ。そして1928年には、<strong class=\"source-bold\">アメリカ国務長官</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケロッグ</strong></span>と<strong class=\"source-bold\">フランス外相</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブリアン</strong></span>が主導して、各国が<strong class=\"source-bold\">戦争<ruby>放棄<rt>ほうき</rt></ruby>を約束</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">不戦条約</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケロッグ・ブリアン条約</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">協定</strong></span>）】</strong>が成立した。この条約は、もともと<strong class=\"source-bold\">フランス</strong>が「<strong class=\"source-bold\">米仏2国で不戦協定</strong>を結びましょう」って提案したら、<strong class=\"source-bold\">アメリカ</strong>に「それなら<strong class=\"source-bold\">もっとたくさんの国を入れましょう</strong>」って逆提案されたから、15カ国で不戦条約を結ぶことになったんだよ。</p>\n<p>このように、<strong class=\"source-bold\">ドーズ案</strong>でドイツの復興が進むにつれて<strong class=\"source-bold\">ヨーロッパ経済全体が上向きになって、国際関係も安定していた</strong>んだよ。だから、戦間期（第一次世界大戦と第二次世界大戦の間の時期）の20年間で最も安定していた1920年代後半は「<strong class=\"source-bold\">相対的安定期</strong>」なんていわれている。でも、この安定がずっと続くか？っていうと……そうもいかないんだ。だって、<strong class=\"source-bold\">不戦条約は1928年……翌年は世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong>だもんね！。</p>\n<p>さて、今回はこれでおしまい。それじゃあ最後に年号 check！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">‼</span> <span data-source-color=\"red\" style=\"color:#e52715\">年号</span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">のツボ</span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ヴェルサイユ条約</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1919</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span> それ行く ヴェルサイユ）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ワシントン会議</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1921</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>引<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>引<rt>1</rt></ruby></strong></span>けない 海軍軍縮）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ラパロ条約</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1922</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>弾<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span>ぞ<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>プー<rt>2</rt></ruby><ruby>プー<rt>2</rt></ruby></strong></span> ラッパ吹く［ラパロ条約］）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ドーズ案</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1924</strong></span>］</td><td>（ドーズ案は <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>特<rt>19</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>よ<rt>4</rt></ruby></strong></span>かった）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ロカルノ条約</strong></td><td>［19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">25</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>都<rt>2</rt></ruby><ruby>合<rt>5</rt></ruby></strong></span>つけてよ ラインラント）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">不戦条約</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1928</strong></span>］</td><td>（戦争は <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>とっ<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>や<rt>8</rt></ruby></strong></span>めた）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ロンドン軍縮会議</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1930</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>19</rt></ruby><ruby>さ<rt>3</rt></ruby><ruby>ゼロ<rt>0</rt></ruby></strong></span>まで 補助艦削減）</td></tr></tbody></table></div>\n<p>次回は<strong class=\"source-bold\">第一次世界大戦後のヨーロッパ各国</strong>について見ていくよ。今回出てきたことがいろいろ関係しているから、しっかり確認してから進もう！</p>"
};

